//
//  Reference.swift
//  RunGuardCoreTests
//
//  Loads the numbers the Python `acwr` package produced for the same inputs
//  (Fixtures/acwr_reference.json, generated by Fixtures/generate_reference.py)
//  so every Swift result can be checked against the reference implementation.
//
//  Added for RunGuard 2.0 (CAC 2026), AI-assisted, see DISCLOSURE.md
//

import Foundation
import XCTest

/// A JSON number, null (NaN) or the strings "inf"/"-inf".
enum RefValue: Decodable {
    case number(Double), nan, inf, negInf

    init(from decoder: Decoder) throws {
        let c = try decoder.singleValueContainer()
        if c.decodeNil() { self = .nan; return }
        if let d = try? c.decode(Double.self) { self = .number(d); return }
        let s = try c.decode(String.self)
        switch s {
        case "inf": self = .inf
        case "-inf": self = .negInf
        default: throw DecodingError.dataCorruptedError(in: c, debugDescription: "bad value \(s)")
        }
    }

    var double: Double {
        switch self {
        case .number(let d): d
        case .nan: .nan
        case .inf: .infinity
        case .negInf: -.infinity
        }
    }
}

struct RefComponents: Decodable {
    let acute: [RefValue], chronic: [RefValue], acwr: [RefValue]
}

struct RefRescaling: Decodable {
    let n: Int, spearman: Double, pearson: Double
    /// Spearman after rounding both arrays to 9 dp, so mathematically tied
    /// windows tie. See DiagnosticsTests for why this is the exact target.
    let spearman_ties_resolved: Double
    let spearman_ci95: [Double]
}

struct RefThreshold: Decodable {
    let n: Int, percentiles: [String: Double], reference: Double
    let reference_flagged: Int, reference_flagged_fraction: Double, reference_percentile: Double
}

struct RefFinding: Decodable {
    let check: String, severity: String, message: String, dates: [String]
}

struct RefQuality: Decodable {
    let n_days: Int, n_training_days: Int, ok: Bool, findings: [RefFinding]
}

struct RefDiagnostics: Decodable {
    let rescaling: RefRescaling, threshold: RefThreshold, quality: RefQuality
}

struct RefSeries: Decodable {
    let start: String
    let load: [Double]
    let rac: RefComponents?
    let rau: RefComponents?
    let ewma: RefComponents?
    let diagnostics_rac: RefDiagnostics?
    let diagnostics_rau: RefDiagnostics?
    let diagnostics_ewma: RefDiagnostics?
}

struct RefHand: Decodable {
    let spike_rac_last: Double, spike_rau_last: Double, spike_ewma_last: Double
    let ewma_acute_spike_day: Double, ewma_acute_next_day: Double, steady400_ewma_last: Double
    let short20_error: String, outlier_dates: [String], outlier_message: String
    let break_message: String, unit_message: String
}

struct RefStats: Decodable {
    let arr: [Double], percentiles: [String: Double]
    let spearman_vs_index: Double, pearson_vs_index: Double
}

struct Reference: Decodable {
    let generated_by: String
    let gamma400: RefSeries
    let rhythm500: RefSeries
    let lumpy900: RefSeries
    let hand: RefHand
    let stats: RefStats

    static let shared: Reference = {
        let url = Bundle.module.url(forResource: "acwr_reference", withExtension: "json", subdirectory: "Fixtures")!
        return try! JSONDecoder().decode(Reference.self, from: Data(contentsOf: url))
    }()
}

/// UTC calendar so fixture dates like "2026-02-20" map to indices exactly.
let utc: Calendar = {
    var c = Calendar(identifier: .gregorian)
    c.timeZone = TimeZone(identifier: "UTC")!
    return c
}()

func isoDate(_ s: String) -> Date {
    let f = DateFormatter()
    f.calendar = utc
    f.timeZone = utc.timeZone
    f.dateFormat = "yyyy-MM-dd"
    return f.date(from: s)!
}

func isoString(_ d: Date) -> String {
    let f = DateFormatter()
    f.calendar = utc
    f.timeZone = utc.timeZone
    f.dateFormat = "yyyy-MM-dd"
    return f.string(from: d)
}

/// Element-wise comparison that treats NaN == NaN and inf == inf.
func assertSeriesMatch(_ ours: [Double], _ ref: [RefValue], tolerance: Double = 1e-9,
                       _ label: String, file: StaticString = #filePath, line: UInt = #line) {
    XCTAssertEqual(ours.count, ref.count, "\(label): length", file: file, line: line)
    var worst = 0.0
    for (i, (a, r)) in zip(ours, ref.map(\.double)).enumerated() {
        if a.isNaN || r.isNaN {
            XCTAssert(a.isNaN && r.isNaN, "\(label)[\(i)]: ours \(a) ref \(r)", file: file, line: line)
        } else if a.isInfinite || r.isInfinite {
            XCTAssertEqual(a, r, "\(label)[\(i)]: ours \(a) ref \(r)", file: file, line: line)
        } else {
            worst = max(worst, abs(a - r))
            XCTAssertEqual(a, r, accuracy: tolerance, "\(label)[\(i)]", file: file, line: line)
        }
    }
    print("\(label): \(ours.count) values, max |ours - python| = \(worst)")
}
